import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"Integration plan — making the int4 kernel a substrate citizen","description":"","frontmatter":{"title":"Integration plan — making the int4 kernel a substrate citizen","type":"report","date":"2026-10-27T00:00:00.000Z","status_note":"design + first steps. The kernel today is a demo: it bypasses\\n`kernelopt` entirely (no `Rewrite`, no `KernelSink`, no cost model, no\\ncertificate, no sieve)."},"headers":[],"relativePath":"graphopt/project/reports/2026-10-27-substrate-integration.md","filePath":"vendored/graphopt/project/reports/2026-10-27-substrate-integration.md"}'),a={name:`graphopt/project/reports/2026-10-27-substrate-integration.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="integration-plan-—-making-the-int4-kernel-a-substrate-citizen" tabindex="-1">Integration plan — making the int4 kernel a substrate citizen <a class="header-anchor" href="#integration-plan-—-making-the-int4-kernel-a-substrate-citizen" aria-label="Permalink to “Integration plan — making the int4 kernel a substrate citizen”">​</a></h1><p><strong>Date:</strong> 2026-10-27</p><h2 id="what-exists-and-what-it-costs-us" tabindex="-1">What exists, and what it costs us <a class="header-anchor" href="#what-exists-and-what-it-costs-us" aria-label="Permalink to “What exists, and what it costs us”">​</a></h2><table tabindex="0"><thead><tr><th>piece</th><th>today</th><th>consequence</th></tr></thead><tbody><tr><td>int4 GEMV</td><td>a Triton function in <code>bench/drivers/probes/awq/</code></td><td>not minted, not priced, not certified</td></tr><tr><td>routing</td><td>a hand-typed dict of <code>(in, out) -&gt; config</code></td><td>does not generalise to new shapes</td></tr><tr><td>referee</td><td><code>bench/benchkit/regime.py</code> (shipped, tested)</td><td>the one piece already production-shaped</td></tr><tr><td>cost model</td><td><code>mlopt_core</code> roofline/profile, calibrated per machine</td><td>unused by the kernel path</td></tr><tr><td>sieve</td><td><code>kernelopt</code> derivability + novelty</td><td>never sees these kernels</td></tr></tbody></table><h2 id="step-1-—-name-the-operations" tabindex="-1">Step 1 — name the operations <a class="header-anchor" href="#step-1-—-name-the-operations" aria-label="Permalink to “Step 1 — name the operations”">​</a></h2><p>Add int4 primitives to the kernel vocabulary so a kernel is a <em>term</em>, not a function:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>op:packed_load(in, out/8) -&gt; i32[in, out/8]</span></span>
<span class="line"><span>op:dequant    (i32, i32 qzeros, f16 scales, group) -&gt; f16[in, out]</span></span>
<span class="line"><span>op:gemv_int4  (f16[1,in], dequant) -&gt; f16[1,out]</span></span></code></pre></div><p>With these, the kernel becomes a composition the sink can price and the sieve can compare against <code>KERNEL_PRIOR_ART_RULES</code> — which is what makes &quot;is this novel&quot; answerable at all.</p><h2 id="step-2-—-price-it-with-the-machine-not-a-constant" tabindex="-1">Step 2 — price it with the machine, not a constant <a class="header-anchor" href="#step-2-—-price-it-with-the-machine-not-a-constant" aria-label="Permalink to “Step 2 — price it with the machine, not a constant”">​</a></h2><p><code>scripts/calibrate_profile.py</code> already measures bandwidth and launch overhead per machine. The dispatch decision must be:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>route(shape) = argmin over {ours, marlin, awq_gemm, matmul}</span></span>
<span class="line"><span>                 of predicted_us(shape, arm, profile)</span></span></code></pre></div><p>with <code>predicted_us</code> = bytes ÷ measured bandwidth + overheads. Today&#39;s routing table is a hardcoded dict measured on one laptop; it should be <em>emitted</em> from the calibrated cost model, and re-emitted per machine.</p><h2 id="step-3-—-gate-the-search-on-the-referee" tabindex="-1">Step 3 — gate the search on the referee <a class="header-anchor" href="#step-3-—-gate-the-search-on-the-referee" aria-label="Permalink to “Step 3 — gate the search on the referee”">​</a></h2><p>The search must score candidates with <code>regime.blocked_paired</code> (eviction, shuffled rounds) and reject any candidate whose <code>max|Δ|</code> exceeds tolerance <strong>immediately before timing</strong>. Both rules exist because we lost a week to their absence: a broken kernel looked 3× fast, and a patch that never fired looked flat.</p><h2 id="step-4-—-let-the-mint-propose-the-structure" tabindex="-1">Step 4 — let the mint propose the structure <a class="header-anchor" href="#step-4-—-let-the-mint-propose-the-structure" aria-label="Permalink to “Step 4 — let the mint propose the structure”">​</a></h2><p>The template space (GEMV / tiled / split-k × load width × tiles × output dtype) is authored by hand; the search picks within it. Getting the <em>machine</em> to propose kernels means the vocabulary from Step 1 plus a cost model that can rank structures it has never run — that is the research question, and it is not answered here.</p><h2 id="what-i-would-not-do-next" tabindex="-1">What I would not do next <a class="header-anchor" href="#what-i-would-not-do-next" aria-label="Permalink to “What I would not do next”">​</a></h2><ul><li>More config sweeps. Every sweep lands at ~42 % of roofline; the remaining 2.4× is unpack codegen, not a parameter.</li><li>More end-to-end runs on this box. 100 rounds at 13 % spread cannot resolve a 2 % effect; the last three runs said −3.2 %, −4.1 %, −2.0 % with sign tests of 4/6, 16/30, 46/100 — noise.</li></ul>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};